import{_ as o,B as n,o as d,c as l,a8 as p,a,E as t,f as s}from"./chunks/framework.CNIpabDg.js";const T=JSON.parse(`{"title":"HTTP","description":"Portable bounded HTTP/1 response parsing, body decoding and Xila's streaming network devices.","frontmatter":{"layout":"doc","docType":"explanation","description":"Portable bounded HTTP/1 response parsing, body decoding and Xila's streaming network devices."},"headers":[],"relativePath":"explanation/architecture/libraries/http.md","filePath":"explanation/architecture/libraries/http.md","lastUpdated":1793145952000}`),h={name:"explanation/architecture/libraries/http.md"};function c(u,e,g,b,k,m){const i=n("HostReference"),r=n("CodeReference");return d(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[5]||(e[5]=p(`<h1 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h1><p>Core #522 extracted the reusable <code>xila_http</code> package under <code>libraries/http</code>. It provides <code>no_std</code> HTTP/1 request helpers, response-head parsing, borrowed URL parsing and incremental body decoding. The default feature set does not require a heap allocator; the optional <code>alloc</code> feature provides URL formatting helpers.</p><h2 id="framing-and-ownership" tabindex="-1">Framing and ownership <a class="header-anchor" href="#framing-and-ownership" aria-label="Permalink to &quot;Framing and ownership&quot;">​</a></h2><p><code>parse_response_head::&lt;N&gt;</code> borrows a caller-managed header buffer and returns an incomplete result when more bytes are needed. Its generic <code>N</code> header capacity contributes <code>N × size_of::&lt;httparse::Header&gt;()</code> of parser stack storage; the caller must also bound header bytes. Header names and transfer coding names are compared case-insensitively.</p><p><code>BodyDecoder</code> accepts fragmented input and decodes chunked bodies <strong>in place</strong>, discarding chunk extensions and trailers. The parser also handles Content-Length, close-delimited responses, informational 1xx replies and responses that cannot carry a body (including HEAD/204/304). It detects truncated bodies when the stream ends. Protocol upgrades, pipelining and content decompression are not implemented.</p><h2 id="http-https-devices" tabindex="-1">HTTP/HTTPS devices <a class="header-anchor" href="#http-https-devices" aria-label="Permalink to &quot;HTTP/HTTPS devices&quot;">​</a></h2><p>Xila&#39;s VFS HTTP and HTTPS devices now stream response data through a <strong>single 2 KiB buffer per opening</strong>, with reader backpressure instead of accumulating the entire download. Device reads return the original response headers followed by <strong>decoded body bytes</strong>: callers must not decode HTTP chunk framing a second time. Head reads may be fragmented, so read through the empty line before interpreting body bytes.</p><p>The reported native exchange peak of 2,592 bytes for both 4 KiB and 4 MiB generated downloads excludes socket storage, TLS and application buffers. HTTPS separately uses a 16 KiB + 256-byte receive record buffer and a 16 KiB send record buffer. Core #524 fixed reception of maximum-size TLS records and added optional tests against a real local TLS 1.3 server. TLS certificate policy, public-server interoperability and MCU use are <strong>not</strong> established by those tests.</p><p>Sockets are reclaimed through the Network runner after queued traffic and FIN/RST processing. Cancelled exchanges stop their worker, and abandoned shutdowns have a bounded cleanup window.</p><h2 id="validation-and-boundaries" tabindex="-1">Validation and boundaries <a class="header-anchor" href="#validation-and-boundaries" aria-label="Permalink to &quot;Validation and boundaries&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila_http</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-features</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-network</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignored</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nocapture</span></span></code></pre></div><p>The HTTPS integration test needs Python 3 and OpenSSL and is intentionally ignored by default. Tests cover chunking, fragmented heads, premature EOF, response variants and memory allocation behavior. For protocol sockets and control-plane integration see <a href="/explanation/architecture/subsystems/network.html">Network</a>.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2>`,13)),a("ul",null,[a("li",null,[t(i,{crate:"xila_http"}),e[0]||(e[0]=s(" — portable HTTP library Rustdoc.",-1))]),a("li",null,[t(r,{path:"libraries/http/README.md"}),e[1]||(e[1]=s(" — formats and memory bounds.",-1))]),a("li",null,[t(r,{path:"libraries/http/src/framing.rs"}),e[2]||(e[2]=s(" — incremental HTTP framing.",-1))]),a("li",null,[t(r,{repo:"platforms",path:"drivers/shared/src/devices/http_exchange.rs"}),e[3]||(e[3]=s(" — VFS stream transport.",-1))]),a("li",null,[t(r,{repo:"platforms",path:"drivers/shared/src/devices/https_client.rs"}),e[4]||(e[4]=s(" — HTTPS device.",-1))])])])}const y=o(h,[["render",c]]);export{T as __pageData,y as default};
